-- 시장 자료 팩 2단계 (10-27): Discussion Material 을 제안서 데이터 소스로 쓰기 위한 테이블
-- 1) 시장 지표 일별·월별 값(환율·KOSPI·유가·아파트값): 주요 이슈 장표 차트용
-- 2) 주요 이슈(시점별로 바뀌는 내용): 중요도·작성일로 골라 장표에 넣는다 (양식은 고정, 이슈는 가변)
-- 3) 일별 금리 보강(국고 2·3·5년, 회사채 AA-·BBB- '22년~): 금리 동향 차트·국고 대비 스프레드
-- 4) NH 리서치 기준금리 경로(10/22 공개 코멘트) + 실적: 금리 전망표
-- 값은 scripts/local/market_pack.py (로컬 수집, 공개 출처) 로 만든 SQL 이다.

create table if not exists ref.market_series (
  series_key text primary key,
  label_ko   text not null,
  unit       text not null,
  source     text not null,
  cycle      text not null default 'D' check (cycle in ('D', 'M'))
);
insert into ref.market_series (series_key, label_ko, unit, source, cycle) values
  ('usdkrw', '원/달러 환율', '원', '한국은행 ECOS(매매기준율)', 'D'),
  ('kospi', 'KOSPI', 'pt', '한국은행 ECOS(한국거래소)', 'D'),
  ('brent', '브렌트유', '달러/배럴', 'FRED(Brent 현물)', 'D'),
  ('apt_seoul', 'KB 아파트 매매가격지수(서울)', '지수', '한국은행 ECOS(KB국민은행)', 'M'),
  ('apt_all', 'KB 주택 매매가격지수(전국)', '지수', '한국은행 ECOS(KB국민은행)', 'M')
on conflict (series_key) do update set label_ko = excluded.label_ko, unit = excluded.unit, source = excluded.source, cycle = excluded.cycle;

create table if not exists raw.market_daily (
  series_key text not null references ref.market_series (series_key),
  dt         date not null,
  value      numeric not null,
  fetched_at timestamptz not null default now(),
  primary key (series_key, dt)
);

create table if not exists ref.market_issues (
  issue_id     int generated always as identity primary key,
  topic        text not null,                 -- 장표 소제목 (예: 국제유가 급등)
  as_of        date not null,                 -- 내용 기준일
  valid_until  date not null,                 -- 이 날짜 이후 장표에서 빼기
  priority     int  not null check (priority between 1 and 5), -- 발행시장 영향 중요도(5 높음)
  impact       text not null,                 -- 금리 상방 / 금리 하방 / 수급 우호 / 수급 부담 / 추가 인상 근거 ...
  points       jsonb not null,                -- 본문 글머리 ["...", "..."]
  chart_series text,                          -- market_daily 키 또는 'maturity' (시장 만기도래), null 이면 차트 없음
  chart_title  text,
  sources      jsonb not null default '[]',   -- [{title, url, date}]
  section      text not null default 'issue' check (section in ('issue', 'supply')) -- supply = 시장 수급(만기 집중·정책 자금): 만기도래 및 수급 장표에
);
comment on table ref.market_issues is '제안서 주요 이슈 장표 내용. 양식은 고정, 이슈는 중요도·기준일로 매번 고른다';

create or replace view mart.v_market_daily as
select d.series_key, s.label_ko, s.unit, s.source as source_label, s.cycle, d.dt, d.value
from raw.market_daily d join ref.market_series s using (series_key);

create or replace view mart.v_market_issues as
select issue_id, topic, as_of, valid_until, priority, impact, points, chart_series, chart_title, sources, section
from ref.market_issues;

grant select on mart.v_market_daily, mart.v_market_issues to anon, authenticated;

-- 로컬 수집 스크립트가 서비스 키로 넣는 함수 (raw.rates 는 기존 ingest_put_rates 사용)
-- p_items: [{dt: 'YYYY-MM-DD', value: number}]
create or replace function public.ingest_put_market(p_series_key text, p_items jsonb)
returns int
language plpgsql
security definer
set search_path = ''
as $$
declare n int;
begin
  insert into raw.market_daily (series_key, dt, value)
  select p_series_key, (x ->> 'dt')::date, (x ->> 'value')::numeric
  from jsonb_array_elements(p_items) x
  on conflict (series_key, dt) do update set value = excluded.value, fetched_at = now();
  get diagnostics n = row_count;
  return n;
end;
$$;
revoke execute on function public.ingest_put_market(text, jsonb) from public, anon, authenticated;
grant execute on function public.ingest_put_market(text, jsonb) to service_role;

